.plan-sheet:
margin: 28px 0 0;
  padding: 20px;
  border: 1px solid var(--border, #d5d5d5);
  border-radius: 10px;
  
  background: #fff;
  color: #111;

.plan-sheet__codes:
display: flex;
  gap: 12mm;
  align-items: flex-start;
  flex-wrap: wrap;
  margin: 6mm 0;

.plan-sheet__ordinal:
display: inline-block;
  min-width: 20px;
  margin-right: 6px;
  padding: 1px 6px;
  border-radius: 999px;
  background: #111;
  color: #fff;
  font-weight: 700;
  text-align: center;

.plan-sheet__note:
margin: 4mm 0;
  padding: 8px 10px;
  border-left: 3px solid #111;
  background: #f4f4f4;
  font-size: 13px;

.plan-sheet__list th,\r\n.plan-sheet__li:
padding: 4px 6px;
  border-bottom: 1px solid #ddd;
  text-align: left;
  vertical-align: top;

.plan-sheet__foot:
margin-top: 6mm;
  padding-top: 3mm;
  border-top: 1px solid #ddd;
  font-size: 10px;
  color: #666;

@media print:
body { background: #fff; }
  body * { visibility: hidden !important; }
  .plan-sheet, .plan-sheet * { visibility: visible !important; }
  .plan-sheet {
    position: absolute;
    left: 0;
    top: 0;
    width: 100%;
    margin: 0;
    padding: 0;
    border: 0;
  }
  
  .plan-sheet__codes, .plan-sheet__code { break-inside: avoid; page-break-inside: avoid; }
  .plan-sheet__list tr { break-inside: avoid; page-break-inside: avoid; }
